namespace Bookstore.Ordering.Domain;

public sealed class DomainException(string code, string message) : Exception(message)
{
    public string Code { get; } = code;
}

// Generated by Ordering, not by the database: the id exists before the order is saved.
public readonly record struct OrderId(Guid Value)
{
    public static OrderId New() => new(Guid.CreateVersion7());

    public override string ToString() => Value.ToString();
}

public sealed record Money(decimal Amount, string Currency)
{
    public static Money Zero(string currency) => new(0m, currency);

    // Each line is rounded to two decimals, midpoint away from zero (Requirements Analysis series).
    public Money Times(int quantity) => new(Math.Round(Amount * quantity, 2, MidpointRounding.AwayFromZero), Currency);

    public static Money operator +(Money left, Money right) =>
        left.Currency == right.Currency
            ? new Money(left.Amount + right.Amount, left.Currency)
            : throw new DomainException("money.currency-mismatch", $"Cannot add {right.Currency} to {left.Currency}.");
}

// Until post 10 the buyer comes from the request; then it comes from the access token.
public sealed record Buyer(string Name, string Email);
